int naive = 0;
for (int size = 0; size < 1000; size++) {
    naive += size;            // grow by one: copy everything stored
}

int capacity = 1;
int factor = 0;
for (int size = 0; size < 1000; size++) {
    if (size == capacity) {   // only when the array is full
        factor += size;
        capacity *= 2;
    }
}

System.out.println(naive + " " + factor);

