Object[] data = new Object[0];
int size = 0;

void add(Object value) {
    Object[] bigger = new Object[size + 1];
    System.arraycopy(data, 0, bigger, 0, size);
    bigger[size] = value;
    data = bigger;
    size++;
}

int size = 1000;
int copiesForNextAdd = size;
int copiesToBuildFromEmpty = size * (size - 1) / 2;
